// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.capture/** * NOUS — Voice Activity Detector (VAD). * * Stage 4 of the audio capture pipeline. Determines whether a given audio * chunk contains human speech or just background noise / silence. Used by: * *  - [AudioCapturePipeline] — to tag each emitted chunk with a voice flag. *  - [com.roshan.persona.voice.wakeword.WakeWordDetector] — as a pre-filter *    to skip wake-word inference on silent chunks (saves ~60 % battery per *    the strategy doc §4 "Battery Optimization"). *  - ConversationEngine (Module 5 §12) — silence detection → end-of-turn. * * ## Performance budget * *  - Target: < 10 ms per 20 ms chunk (§15 Performance Budgets). *  - Must be deterministic and stateless per chunk for testability. * * ## Aggressiveness * * Modeled after WebRTC's `vad_set_mode`: *  - 0 = quality (least aggressive, most sensitive) *  - 1 = bitrate *  - 2 = aggressive (default for NOUS) *  - 3 = very aggressive (highest false-positive rejection) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 Battery Optimization, §15 Performance Budgets</a> */sealed interface VoiceActivityDetector {    /**     * Decide whether [chunk] contains voice.     *     * @param chunk 16 kHz, 16-bit PCM, 20 ms = 320 samples.     * @return true if voice detected, false for silence/noise.     */    fun hasVoice(chunk: ShortArray): Boolean    /** Aggressiveness level (0–3). Higher = more aggressive rejection. */    val aggressiveness: Int    // ──────────────────────────────────────────────────────────────────────    /**     * Energy-based VAD — pure Kotlin, no native deps.     *     * Computes short-term energy and zero-crossing rate, then applies a     * threshold. This is the fallback used during early development (before     * the WebRTC JNI ships in :native:webrtc) and as a deterministic test     * stub.     *     * It's deliberately simple — the goal is "good enough to gate the wake     * word model so we don't burn CPU on silence", not "publishable VAD".     */    class EnergyBased(        override val aggressiveness: Int = DEFAULT_AGGRESSIVENESS,        private val energyThreshold: Float = DEFAULT_ENERGY_THRESHOLD,        private val zcrThreshold: Float = DEFAULT_ZCR_THRESHOLD,    ) : VoiceActivityDetector {        init {            require(aggressiveness in 0..3) { "aggressiveness must be 0..3, got $aggressiveness" }        }        override fun hasVoice(chunk: ShortArray): Boolean {            require(chunk.size == AudioCapturePipeline.CHUNK_SAMPLES) {                "VAD expects ${AudioCapturePipeline.CHUNK_SAMPLES} samples, got ${chunk.size}"            }            // 1. Short-term energy (RMS).            var sumSq = 0L            for (s in chunk) {                val v = s.toInt()                sumSq += v.toLong() * v.toLong()            }            val rms = kotlin.math.sqrt(sumSq.toDouble() / chunk.size).toFloat()            // 2. Zero-crossing rate.            var zcr = 0            for (i in 1 until chunk.size) {                if ((chunk[i - 1].toInt() < 0) != (chunk[i].toInt() < 0)) zcr++            }            val zcrRate = zcr.toFloat() / chunk.size            // 3. Aggressiveness scales the energy threshold up (reject more).            val effEnergyThreshold = energyThreshold * (1f + 0.5f * aggressiveness)            // Voice: loud enough + not too noisy (low-mid ZCR).            // Pure noise (e.g., steady fan) often has high ZCR; silence has            // both low energy and high ZCR (random fluctuations).            return rms >= effEnergyThreshold && zcrRate <= zcrThreshold        }        companion object {            const val DEFAULT_AGGRESSIVENESS = 2            // Tuned for 16-bit PCM at 16 kHz. RMS in raw sample units.            const val DEFAULT_ENERGY_THRESHOLD = 800f            const val DEFAULT_ZCR_THRESHOLD = 0.35f        }    }    // ──────────────────────────────────────────────────────────────────────    /**     * Always-on / always-off stub for tests.     *     *  - [AlwaysVoice] — every chunk reports voice (drives downstream code     *    through the "voice" branch deterministically).     *  - [NeverVoice] — every chunk reports silence (drives the "skip"     *    branch).     */    class AlwaysVoice(override val aggressiveness: Int = 2) : VoiceActivityDetector {        override fun hasVoice(chunk: ShortArray): Boolean = true    }    class NeverVoice(override val aggressiveness: Int = 2) : VoiceActivityDetector {        override fun hasVoice(chunk: ShortArray): Boolean = false    }}// ──────────────────────────────────────────────────────────────────────────// AGC — Automatic Gain Control (Layer 3 of the pipeline).// Kept in this file because it's a small, single-purpose stage and Module 5// §5 lists AGC + VAD together under "audio processing".// ──────────────────────────────────────────────────────────────────────────/** * NOUS — Automatic Gain Control. * * Normalizes volume: whisper → normal, shout → normal. Prevents clipping and * distortion so downstream STT gets consistent levels. Adapts to the user's * distance from the microphone. * * Implementation: simple digital compressor/expander with a fixed target RMS. * Good enough for STT; the real "Adaptive Noise Cancellation" upgrade * (§Review-2 #11) replaces this with a learned per-user filter. * * @param targetRms  target RMS level in raw 16-bit sample units (3000 ≈ -24 dBFS). * @param maxGain    maximum gain factor (prevent amplifying pure noise). */class AutomaticGainControl(    private val targetRms: Float = DEFAULT_TARGET_RMS,    private val maxGain: Float = DEFAULT_MAX_GAIN,    private val minGain: Float = DEFAULT_MIN_GAIN,) {    /** Apply gain to one chunk so its RMS approaches [targetRms]. */    fun apply(input: ShortArray): ShortArray {        require(input.isNotEmpty()) { "AGC: input chunk must not be empty" }        var sumSq = 0L        for (s in input) {            val v = s.toInt()            sumSq += v.toLong() * v.toLong()        }        val currentRms = kotlin.math.sqrt(sumSq.toDouble() / input.size).toFloat()        // If the chunk is essentially silent, don't amplify noise.        if (currentRms < SILENCE_RMS) return input.copyOf()        val rawGain = targetRms / currentRms        val gain = rawGain.coerceIn(minGain, maxGain)        val out = ShortArray(input.size)        for (i in input.indices) {            val scaled = (input[i].toInt() * gain).toInt()            out[i] = scaled.coerceIn(Short.MIN_VALUE.toInt(), Short.MAX_VALUE.toInt()).toShort()        }        return out    }    companion object {        const val DEFAULT_TARGET_RMS = 3000f        const val DEFAULT_MAX_GAIN = 10f        const val DEFAULT_MIN_GAIN = 0.1f        const val SILENCE_RMS = 50f    }}